package com.meowcape.mixologyplus;

import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * When you hold the digweed and the potion it should go on, both items get
 * a steady outline in the inventory, so it is clear which two to use on
 * each other.
 */
@Singleton
public class DigweedInventoryOverlay extends WidgetItemOverlay
{
	private static final int DIGWEED_ITEM_ID = ItemID.MM_LAB_SPECIAL_HERB;

	private final MixologyState state;
	private final MixologyConfig config;
	private final ItemManager itemManager;

	@Inject
	private DigweedInventoryOverlay(MixologyState state, MixologyConfig config, ItemManager itemManager)
	{
		this.state = state;
		this.config = config;
		this.itemManager = itemManager;
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		MixPotion target = state.getDigweedTarget();
		// always shown while combining is the current step; otherwise only
		// if the highlight setting is on
		boolean isStep = state.getLabAction() == MixologyState.LabAction.USE_DIGWEED;
		if (!(isStep || config.digweedUseHighlight()) || !state.isInLab() || target == null || !state.isDigweedComboReady())
		{
			return;
		}
		boolean match = itemId == DIGWEED_ITEM_ID
			|| itemId == target.getUnfinishedItemId()
			|| itemId == target.getFinishedItemId();
		if (!match)
		{
			return;
		}
		// outline the item's own shape (like the ground items / inventory
		// tags style) rather than a box around the slot
		BufferedImage outline = itemManager.getItemOutline(itemId, widgetItem.getQuantity(), config.digweedColor());
		if (outline == null)
		{
			return;
		}
		Rectangle b = widgetItem.getCanvasBounds();
		graphics.drawImage(outline, b.x, b.y, null);
	}
}

package com.meowcape.mixologyplus;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A short, soft yellow tint over the game view when a digweed becomes
 * ready to pick: two quick pulses that fade out within about a second.
 * No text, and drawn under the game interface.
 */
@Singleton
public class DigweedScreenFlash extends Overlay
{
	private static final long DURATION_MS = 1100;
	private static final int PULSES = 2;
	private static final int MAX_ALPHA = 70;

	private final Client client;
	private final MixologyState state;
	private final MixologyConfig config;

	@Inject
	private DigweedScreenFlash(Client client, MixologyState state, MixologyConfig config)
	{
		this.client = client;
		this.state = state;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		long elapsed = System.currentTimeMillis() - state.getFlashStartMs();
		if (state.getFlashStartMs() == 0 || elapsed < 0 || elapsed >= DURATION_MS || !state.isInLab())
		{
			return null;
		}
		double t = elapsed / (double) DURATION_MS;
		// two sine pulses, fading out over the whole flash
		double pulse = Math.abs(Math.sin(t * Math.PI * PULSES));
		int alpha = (int) Math.round(MAX_ALPHA * pulse * (1.0 - t));
		if (alpha <= 0)
		{
			return null;
		}
		Color c = config.digweedColor();
		g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha));
		g.fillRect(0, 0, client.getCanvasWidth(), client.getCanvasHeight());
		return null;
	}
}

package com.meowcape.mixologyplus;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * Works out which levers to pull, in order, to get a recipe into the
 * mixer.
 *
 * The mixer holds up to three pastes, filling slot 0, 1, 2 in order, and
 * the potion is decided by which three pastes it holds, in any order. When
 * it is already full, a new paste pushes the OLDEST one out. So leftovers
 * from an earlier mix can't simply be skipped as "already done": whether a
 * leftover survives depends on how many pulls come after it. The planner
 * simulates the mixer and returns the shortest sequence that ends with
 * exactly the recipe.
 */
final class LeverPlanner
{
	private LeverPlanner()
	{
	}

	/**
	 * @param slots  mixer slot values, oldest first: 0 empty, 1 mox, 2 aga,
	 *               3 lye
	 * @param recipe recipe code such as "MAL"
	 * @return levers to pull in order (0 mox, 1 aga, 2 lye); empty when
	 * the mixer already holds the recipe
	 */
	static int[] plan(int[] slots, String recipe)
	{
		List<Integer> mixer = new ArrayList<>();
		for (int v : slots)
		{
			if (v >= 1 && v <= 3)
			{
				mixer.add(v - 1);
			}
		}
		int[] want = counts(recipe);

		// the natural plan first: keep what fits, pull the rest in recipe
		// order; used whenever it really works out, so a clean mixer always
		// gets the familiar order
		int[] natural = naturalPlan(mixer, recipe);
		if (natural != null && matches(simulate(mixer, natural), want))
		{
			return natural;
		}

		// otherwise the shortest sequence that ends with the recipe; three
		// pulls always suffice, since they replace everything
		for (int len = 1; len <= 3; len++)
		{
			int[] found = search(mixer, want, new int[len], 0, recipe);
			if (found != null)
			{
				return found;
			}
		}
		return natural != null ? natural : new int[0];
	}

	/**
	 * Recipe pastes not already covered by what is in the mixer, in recipe
	 * order; null if the mixer has no room for them without pushing pastes
	 * out.
	 */
	private static int[] naturalPlan(List<Integer> mixer, String recipe)
	{
		int[] have = new int[3];
		for (int c : mixer)
		{
			have[c]++;
		}
		List<Integer> pulls = new ArrayList<>();
		for (char ch : recipe.toCharArray())
		{
			int c = MixPotion.componentIndex(ch);
			if (have[c] > 0)
			{
				have[c]--;
			}
			else
			{
				pulls.add(c);
			}
		}
		if (mixer.size() + pulls.size() > 3)
		{
			return null;
		}
		return pulls.stream().mapToInt(Integer::intValue).toArray();
	}

	/**
	 * Depth-first search over pull sequences of a fixed length. Levers are
	 * tried in recipe order, so among equally short plans the one closest
	 * to the recipe's own order wins.
	 */
	private static int[] search(List<Integer> mixer, int[] want, int[] seq, int pos, String recipe)
	{
		if (pos == seq.length)
		{
			return matches(simulate(mixer, seq), want) ? seq.clone() : null;
		}
		for (int lever : leverOrder(recipe))
		{
			seq[pos] = lever;
			int[] found = search(mixer, want, seq, pos + 1, recipe);
			if (found != null)
			{
				return found;
			}
		}
		return null;
	}

	/**
	 * The recipe's levers first (in recipe order), then any others.
	 */
	private static int[] leverOrder(String recipe)
	{
		List<Integer> order = new ArrayList<>();
		for (char ch : recipe.toCharArray())
		{
			int c = MixPotion.componentIndex(ch);
			if (!order.contains(c))
			{
				order.add(c);
			}
		}
		for (int c = 0; c < 3; c++)
		{
			if (!order.contains(c))
			{
				order.add(c);
			}
		}
		return order.stream().mapToInt(Integer::intValue).toArray();
	}

	/**
	 * The mixer after these pulls: each paste goes on the end, and when it
	 * is already full the oldest drops out.
	 */
	static List<Integer> simulate(List<Integer> mixer, int[] pulls)
	{
		List<Integer> out = new ArrayList<>(mixer);
		for (int lever : pulls)
		{
			if (out.size() == 3)
			{
				out.remove(0);
			}
			out.add(lever);
		}
		return out;
	}

	private static boolean matches(List<Integer> mixer, int[] want)
	{
		if (mixer.size() != 3)
		{
			return false;
		}
		int[] have = new int[3];
		for (int c : mixer)
		{
			have[c]++;
		}
		return Arrays.equals(have, want);
	}

	private static int[] counts(String recipe)
	{
		int[] c = new int[3];
		for (char ch : recipe.toCharArray())
		{
			c[MixPotion.componentIndex(ch)]++;
		}
		return c;
	}
}

package com.meowcape.mixologyplus;

/**
 * The ten Mastering Mixology potions, declared in ORDER VARBIT VALUE order
 * (varbit value = ordinal + 1). WARNING: this order does NOT match item-id
 * order for AAM/AAL and LLM/LLA.
 *
 * Points are the ordered hand-in rewards (mox/aga/lye) and xp is the
 * Herblore experience for depositing it as an order, both from the wiki.
 * The code is the recipe in the order the plugin asks you to pull the
 * levers (same-lever pulls are always next to each other).
 */
public enum MixPotion
{
	MMM("Mammoth-might mix", "MMM", 60, 190, 20, 0, 0, 30011, 30021),
	MMA("Mystic mana amalgam", "MMA", 63, 215, 20, 10, 0, 30012, 30022),
	MML("Marley's moonlight", "MML", 66, 240, 20, 0, 10, 30013, 30023),
	AAA("Alco-augmentator", "AAA", 60, 190, 0, 20, 0, 30014, 30024),
	AAM("Azure aura mix", "AAM", 69, 265, 10, 20, 0, 30016, 30026),
	AAL("Aqualux amalgam", "AAL", 72, 290, 0, 20, 10, 30015, 30025),
	LLL("Liplack liquor", "LLL", 60, 190, 0, 0, 20, 30017, 30027),
	LLM("Megalite liquid", "LLM", 75, 315, 10, 0, 20, 30019, 30029),
	LLA("Anti-leech lotion", "LLA", 78, 340, 0, 10, 20, 30018, 30028),
	MAL("Mixalot", "MAL", 81, 365, 20, 20, 20, 30020, 30030);

	private final String displayName;
	private final String code;
	private final int level;
	private final int xp;
	private final int moxPoints;
	private final int agaPoints;
	private final int lyePoints;
	private final int unfinishedItemId;
	private final int finishedItemId;

	MixPotion(String displayName, String code, int level, int xp, int moxPoints, int agaPoints,
		int lyePoints, int unfinishedItemId, int finishedItemId)
	{
		this.displayName = displayName;
		this.code = code;
		this.level = level;
		this.xp = xp;
		this.moxPoints = moxPoints;
		this.agaPoints = agaPoints;
		this.lyePoints = lyePoints;
		this.unfinishedItemId = unfinishedItemId;
		this.finishedItemId = finishedItemId;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public String getCode()
	{
		return code;
	}

	public int getLevel()
	{
		return level;
	}

	public int getXp()
	{
		return xp;
	}

	public int getMoxPoints()
	{
		return moxPoints;
	}

	public int getAgaPoints()
	{
		return agaPoints;
	}

	public int getLyePoints()
	{
		return lyePoints;
	}

	public int getUnfinishedItemId()
	{
		return unfinishedItemId;
	}

	public int getFinishedItemId()
	{
		return finishedItemId;
	}

	/**
	 * @param varbitValue the order TYPE varbit value (1-10); 0 = no order
	 */
	public static MixPotion fromVarbit(int varbitValue)
	{
		int idx = varbitValue - 1;
		return idx >= 0 && idx < values().length ? values()[idx] : null;
	}

	/**
	 * Lever / resin index for a recipe letter: 0 mox, 1 aga, 2 lye.
	 */
	public static int componentIndex(char c)
	{
		return c == 'M' ? 0 : c == 'A' ? 1 : 2;
	}

	public static String modifierName(int modifierVarbitValue)
	{
		switch (modifierVarbitValue)
		{
			case 1:
				return "Agitator";
			case 2:
				return "Retort";
			case 3:
				return "Alembic";
			default:
				return "?";
		}
	}
}

package com.meowcape.mixologyplus;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(MixologyConfig.GROUP)
public interface MixologyConfig extends Config
{
	String GROUP = "mixologyplus";

	enum Strategy
	{
		FASTEST_POINTS("Fastest points"),
		SAVE_PASTES("Most points per paste"),
		MAX_XP("Maximum XP");

		private final String label;

		Strategy(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigItem(
		keyName = "strategy",
		name = "Mode",
		description = "Fastest points: the orders that get you to your target reward quickest. "
			+ "Most points per paste: the orders that get the most out of your pastes, ignoring time (skips weak potions more often). "
			+ "Maximum XP: the orders that give the most Herblore XP for your time",
		position = 0
	)
	default Strategy strategy()
	{
		return Strategy.FASTEST_POINTS;
	}

	@ConfigItem(
		keyName = "targetReward",
		name = "Target reward",
		description = "The shop reward you are saving for. Fastest points mode picks orders to suit its mox/aga/lye price",
		position = 1
	)
	default MixologyReward targetReward()
	{
		return MixologyReward.ALDARIUM;
	}

	@Range(min = 75, max = 250)
	@ConfigItem(
		keyName = "overlayScale",
		name = "Label size %",
		description = "Size of the in-world labels (100 = default, sharpest at 100 or 200)",
		position = 2
	)
	default int overlayScale()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "guideLevers",
		name = "Lever guidance",
		description = "Number the levers in pull order (1st, 2nd, 3rd) and make the next one to pull stand out",
		position = 3
	)
	default boolean guideLevers()
	{
		return true;
	}

	@ConfigItem(
		keyName = "guideStations",
		name = "Station guidance",
		description = "Highlight the station needed by the next unprocessed potion in your inventory",
		position = 4
	)
	default boolean guideStations()
	{
		return true;
	}

	@ConfigItem(
		keyName = "protectRetort",
		name = "Retort misclick guard",
		description = "When the Retort isn't the station you need, its left-click becomes Walk here, so spam-clicking after it finishes "
			+ "can't put your next potion in it. Right-click still works",
		position = 5
	)
	default boolean protectRetort()
	{
		return true;
	}

	@ConfigItem(
		keyName = "guideQuickAction",
		name = "Quick-action flash",
		description = "Flash the agitator/alembic green when the speed-boost click window is open",
		position = 6
	)
	default boolean guideQuickAction()
	{
		return true;
	}

	@ConfigItem(
		keyName = "digweedHighlight",
		name = "Digweed highlight",
		description = "Outline a digweed plant with \"Collect\" above it while it is ready to pick",
		position = 7
	)
	default boolean digweedHighlight()
	{
		return true;
	}

	@ConfigItem(
		keyName = "digweedArrow",
		name = "Digweed waypoint arrow",
		description = "Point the game's hint arrow (also shown on the minimap) at a digweed while it is ready to pick",
		position = 8
	)
	default boolean digweedArrow()
	{
		return true;
	}

	@ConfigItem(
		keyName = "digweedChat",
		name = "Digweed chat message",
		description = "Post a game message when a digweed spawns, saying which potion to use it on",
		position = 9
	)
	default boolean digweedChat()
	{
		return true;
	}

	@ConfigItem(
		keyName = "digweedFlash",
		name = "Digweed screen flash",
		description = "Briefly flash the screen yellow when a digweed is ready to pick",
		position = 10
	)
	default boolean digweedFlash()
	{
		return true;
	}

	@ConfigItem(
		keyName = "digweedUseHighlight",
		name = "Digweed use highlight",
		description = "When you hold the digweed and the potion it should go on, outline both in your inventory so you can use one on the other",
		position = 11
	)
	default boolean digweedUseHighlight()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showProgress",
		name = "Show reward progress",
		description = "A small box showing how far you are towards your target reward, e.g. \"Aldarium 22%\"",
		position = 12
	)
	default boolean showProgress()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showNextStep",
		name = "Show next step",
		description = "Faintly outline where you will go after the current step, with a \"Next:\" label, so you can head there early",
		position = 13
	)
	default boolean showNextStep()
	{
		return true;
	}

	@ConfigSection(
		name = "Colours",
		description = "Colours of the in-world highlights and their labels",
		position = 20,
		closedByDefault = true
	)
	String COLOURS = "colours";

	@Alpha
	@ConfigItem(keyName = "moxColor", name = "Mox lever", description = "Mox lever highlight", section = COLOURS, position = 21)
	default Color moxColor()
	{
		return new Color(90, 130, 255);
	}

	@Alpha
	@ConfigItem(keyName = "agaColor", name = "Aga lever", description = "Aga lever highlight", section = COLOURS, position = 22)
	default Color agaColor()
	{
		return new Color(60, 200, 80);
	}

	@Alpha
	@ConfigItem(keyName = "lyeColor", name = "Lye lever", description = "Lye lever highlight", section = COLOURS, position = 23)
	default Color lyeColor()
	{
		return new Color(235, 70, 70);
	}

	@Alpha
	@ConfigItem(keyName = "vesselColor", name = "Collect (vessel)", description = "Mixing vessel highlight when a mix is ready to collect", section = COLOURS, position = 24)
	default Color vesselColor()
	{
		return Color.WHITE;
	}

	@Alpha
	@ConfigItem(keyName = "stationColor", name = "Station", description = "Station to insert the potion into, and stations working on their own", section = COLOURS, position = 25)
	default Color stationColor()
	{
		return new Color(255, 0, 255);
	}

	@Alpha
	@ConfigItem(keyName = "spamClickColor", name = "Retort spam click", description = "Retort highlight while it needs clicking", section = COLOURS, position = 26)
	default Color spamClickColor()
	{
		return new Color(0, 255, 60);
	}

	@Alpha
	@ConfigItem(keyName = "quickActionColor", name = "Quick-action click", description = "Agitator / alembic flash during the speed-boost click window", section = COLOURS, position = 27)
	default Color quickActionColor()
	{
		return new Color(0, 255, 60);
	}

	@Alpha
	@ConfigItem(keyName = "depositColor", name = "Deposit", description = "Conveyor belt highlight when it's time to deposit", section = COLOURS, position = 28)
	default Color depositColor()
	{
		return new Color(0, 255, 60);
	}

	@Alpha
	@ConfigItem(keyName = "nextStepColor", name = "Next step", description = "Faint outline and label for the next-step preview", section = COLOURS, position = 30)
	default Color nextStepColor()
	{
		return new Color(255, 255, 255, 130);
	}

	@Alpha
	@ConfigItem(keyName = "digweedColor", name = "Digweed", description = "Digweed plant outline, the screen flash, and the digweed / potion outline in your inventory", section = COLOURS, position = 29)
	default Color digweedColor()
	{
		return new Color(255, 220, 60);
	}
}

package com.meowcape.mixologyplus;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.TileObject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/**
 * In-world lab guidance: lever outlines with remaining pull counts for
 * the next mix, the target station, the quick-action flash, and the
 * ready vessel.
 */
@Singleton
public class MixologyLabOverlay extends Overlay
{
	private static final int LABEL_HEIGHT = 120;
	private static final int PLAYER_LABEL_HEIGHT = 240;
	private static final int STATION_LABEL_HEIGHT = 300;
	private static final int SAME_STATION_EXTRA_HEIGHT = 80;

	private final Client client;
	private final MixologyState state;
	private final MixologyConfig config;
	private final MixologyObjects objects;
	private final ModelOutlineRenderer outliner;

	@Inject
	private MixologyLabOverlay(Client client, MixologyState state, MixologyConfig config,
		MixologyObjects objects, ModelOutlineRenderer outliner)
	{
		this.client = client;
		this.state = state;
		this.config = config;
		this.objects = objects;
		this.outliner = outliner;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!state.isInLab())
		{
			return null;
		}

		// pickable digweed despawns in ~20s, so it draws alongside
		// whatever else is on screen, never queued behind it
		if (config.digweedHighlight())
		{
			for (int herbId : state.getReadyHerbObjectIds())
			{
				TileObject herb = objects.get(herbId);
				if (herb != null)
				{
					outliner.drawOutline(herb, 3, config.digweedColor(), 2);
					Color c = config.digweedColor();
					drawLabel(graphics, herb, "Collect", new Color(c.getRed(), c.getGreen(), c.getBlue()));
				}
			}
		}

		// the quick-action window is a two-tick reflex cue: while open it
		// IS the action, overriding whatever the queue was showing
		if (config.guideQuickAction() && state.getQuickActionId() != 0)
		{
			TileObject station = objects.get(state.getQuickActionId());
			if (station != null)
			{
				outliner.drawOutline(station, 5, config.quickActionColor(), 2);
				drawLabel(graphics, station, "Click!", config.quickActionColor(), STATION_LABEL_HEIGHT);
				return null;
			}
		}

		if (config.showNextStep())
		{
			drawNextStep(graphics);
		}

		// otherwise exactly ONE action on screen, in gameplay order
		switch (state.getLabAction())
		{
			case COLLECT_VESSEL:
			{
				TileObject vessel = objects.get(MixologyObjects.VESSEL);
				if (vessel != null)
				{
					outliner.drawOutline(vessel, 3, config.vesselColor(), 2);
					drawLabel(graphics, vessel, "Collect", config.vesselColor());
				}
				break;
			}
			case MIX:
			{
				if (config.guideLevers())
				{
					int next = state.nextLever();
					drawLever(graphics, MixologyObjects.LEVER_MOX, 0, next, config.moxColor());
					drawLever(graphics, MixologyObjects.LEVER_AGA, 1, next, config.agaColor());
					drawLever(graphics, MixologyObjects.LEVER_LYE, 2, next, config.lyeColor());
				}
				break;
			}
			case USE_STATION:
			{
				if (config.guideStations())
				{
					TileObject station = objects.get(state.getActionStationId());
					if (station != null)
					{
						outliner.drawOutline(station, 3, config.stationColor(), 2);
						drawLabel(graphics, station, "Insert", config.stationColor(), STATION_LABEL_HEIGHT);
					}
				}
				break;
			}
			case ATTEND_STATION:
			{
				if (config.guideStations())
				{
					TileObject station = objects.get(state.getActionStationId());
					if (station != null)
					{
						if (state.getActionStationId() == MixologyObjects.STATION_RETORT)
						{
							// the retort speeds up with every click, so keep
							// clicking it while it works; a fast blink says
							// "keep going" rather than "click once"
							boolean on = (System.currentTimeMillis() / 300) % 2 == 0;
							Color spam = config.spamClickColor();
							outliner.drawOutline(station, on ? 5 : 3, spam, 2);
							drawLabel(graphics, station, "Spam click!", on ? spam : spam.darker(), STATION_LABEL_HEIGHT);
						}
						else
						{
							// agitator / alembic: stay here until it finishes;
							// the quick-action flash takes over in click windows
							outliner.drawOutline(station, 3, config.stationColor(), 2);
							drawLabel(graphics, station, "Working...", config.stationColor(), STATION_LABEL_HEIGHT);
						}
					}
				}
				break;
			}
			case USE_DIGWEED:
			{
				// the step happens in the inventory (both items are outlined
				// there); say it above the player so it can't be missed
				MixPotion target = state.getDigweedTarget();
				Player player = client.getLocalPlayer();
				if (target != null && player != null && player.getLocalLocation() != null)
				{
					Color c = config.digweedColor();
					String text = "Use digweed on " + target.getDisplayName();
					graphics.setFont(OverlayFonts.bold(config.overlayScale()));
					OverlayFonts.applyTextHints(graphics, config.overlayScale());
					Point at = Perspective.getCanvasTextLocation(client, graphics, player.getLocalLocation(), text, PLAYER_LABEL_HEIGHT);
					if (at != null)
					{
						graphics.setColor(Color.BLACK);
						graphics.drawString(text, at.getX() + 1, at.getY() + 1);
						graphics.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue()));
						graphics.drawString(text, at.getX(), at.getY());
					}
				}
				break;
			}
			case DEPOSIT:
			{
				// the belt is one object id repeated per segment; the one
				// you deposit at is the segment nearest to you
				Player player = client.getLocalPlayer();
				TileObject conveyor = objects.nearest(MixologyObjects.CONVEYOR,
					player == null ? null : player.getLocalLocation());
				if (conveyor != null)
				{
					outliner.drawOutline(conveyor, 3, config.depositColor(), 2);
					drawLabel(graphics, conveyor, "Deposit", config.depositColor());
				}
				break;
			}
			default:
		}
		return null;
	}

	/**
	 * Labels a lever with the steps it is still used for, keeping their
	 * place in the recipe ("2nd", "1st, 2nd"), or a countdown ("3x", "2x",
	 * "1x") for single-ingredient potions. The lever to
	 * pull next gets a thick, pulsing outline; levers needed later are
	 * drawn in a dimmer colour.
	 */
	private void drawLever(Graphics2D graphics, int objectId, int lever, int nextLever, Color color)
	{
		int[] steps = state.getMixSteps();
		boolean[] done = state.getMixStepDone();
		List<Integer> mine = new ArrayList<>();
		for (int i = 0; i < steps.length; i++)
		{
			if (steps[i] == lever && !done[i])
			{
				mine.add(i + 1);
			}
		}
		if (mine.isEmpty())
		{
			return;
		}
		// single-ingredient potions (all Mox, Aga or Lye) just count down:
		// 3x, 2x, 1x; everything else names the steps in order
		MixPotion target = state.getMixTarget();
		String code = target == null ? "" : target.getCode();
		boolean singleIngredient = code.length() == 3 && code.chars().distinct().count() == 1;
		String order = singleIngredient ? mine.size() + "x" : stepLabel(mine);
		TileObject object = objects.get(objectId);
		if (object == null)
		{
			return;
		}
		if (lever == nextLever)
		{
			// gentle pulse so the next lever reads at a glance
			double phase = (System.currentTimeMillis() % 1000) / 1000.0;
			int alpha = 170 + (int) (85 * Math.abs(Math.sin(phase * Math.PI)));
			Color pulse = new Color(color.getRed(), color.getGreen(), color.getBlue(), alpha);
			outliner.drawOutline(object, 6, pulse, 2);
			drawLabel(graphics, object, order, color);
		}
		else
		{
			Color faded = new Color(color.getRed(), color.getGreen(), color.getBlue(), 110);
			outliner.drawOutline(object, 2, faded, 2);
			drawLabel(graphics, object, order, dim(color));
		}
	}

	/**
	 * An opaque, greyed version of a lever colour for "later" labels.
	 */
	private static Color dim(Color c)
	{
		return new Color((c.getRed() + 160) / 2, (c.getGreen() + 160) / 2, (c.getBlue() + 160) / 2);
	}

	/**
	 * A faint outline and "Next: ..." label on where the step after the
	 * current one happens. Drawn before the current step so the current
	 * highlight always sits on top.
	 */
	private void drawNextStep(Graphics2D graphics)
	{
		TileObject target;
		String text;
		switch (state.getNextAction())
		{
			case COLLECT_VESSEL:
				target = objects.get(MixologyObjects.VESSEL);
				text = "Next: Collect";
				break;
			case MIX:
			{
				int lever = state.nextLever();
				target = objects.get(lever == 1 ? MixologyObjects.LEVER_AGA
					: lever == 2 ? MixologyObjects.LEVER_LYE : MixologyObjects.LEVER_MOX);
				text = "Next: Levers";
				break;
			}
			case USE_STATION:
				target = objects.get(state.getNextStationId());
				text = "Next: Insert";
				break;
			case DEPOSIT:
			{
				Player player = client.getLocalPlayer();
				target = objects.nearest(MixologyObjects.CONVEYOR,
					player == null ? null : player.getLocalLocation());
				text = "Next: Deposit";
				break;
			}
			default:
				return;
		}
		if (target == null)
		{
			return;
		}
		Color c = config.nextStepColor();
		outliner.drawOutline(target, 2, c, 2);
		// labels stay opaque: see-through pixel text looks muddy
		Color label = new Color(c.getRed(), c.getGreen(), c.getBlue());
		boolean station = state.getNextAction() == MixologyState.LabAction.USE_STATION;
		int height = station ? STATION_LABEL_HEIGHT : LABEL_HEIGHT;
		// same station as the current step (a second potion for it): stack
		// the "Next:" label above the current one instead of on top of it
		if (station && state.getNextStationId() == state.getActionStationId())
		{
			height += SAME_STATION_EXTRA_HEIGHT;
		}
		drawLabel(graphics, target, text, dim(label), height);
	}

	/**
	 * Step numbers as one readable label, e.g. "3rd" or "1st, 2nd".
	 */
	static String stepLabel(List<Integer> stepNumbers)
	{
		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < stepNumbers.size(); i++)
		{
			if (i > 0)
			{
				sb.append(", ");
			}
			sb.append(ordinal(stepNumbers.get(i)));
		}
		return sb.toString();
	}

	private static String ordinal(int n)
	{
		return n == 1 ? "1st" : n == 2 ? "2nd" : n == 3 ? "3rd" : n + "th";
	}

	private void drawLabel(Graphics2D graphics, TileObject object, String text, Color color)
	{
		drawLabel(graphics, object, text, color, LABEL_HEIGHT);
	}

	/**
	 * @param height how far above the ground to place the text, in local
	 * units; stations use a taller value so the text clears the game's own
	 * progress bar instead of sitting on top of it
	 */
	private void drawLabel(Graphics2D graphics, TileObject object, String text, Color color, int height)
	{
		// set the font first: the label is centred using its metrics
		graphics.setFont(OverlayFonts.bold(config.overlayScale()));
		OverlayFonts.applyTextHints(graphics, config.overlayScale());
		Point location = Perspective.getCanvasTextLocation(
			client, graphics, object.getLocalLocation(), text, height);
		if (location == null)
		{
			return;
		}
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, location.getX() + 1, location.getY() + 1);
		graphics.setColor(color);
		graphics.drawString(text, location.getX(), location.getY());
	}
}

package com.meowcape.mixologyplus;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Singleton;
import net.runelite.api.TileObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.ObjectID;

/**
 * Live references to the lab's interactive objects, tracked by spawn
 * events (the AGA lever is a decorative object, hence TileObject).
 */
@Singleton
public class MixologyObjects
{
	public static final int LEVER_MOX = ObjectID.MM_LAB_SWITCH_MOX;
	public static final int LEVER_AGA = ObjectID.MM_LAB_SWITCH_AGA;
	public static final int LEVER_LYE = ObjectID.MM_LAB_SWITCH_LYE;
	public static final int STATION_RETORT = ObjectID.MM_LAB_MACHINE_RETORT;
	public static final int STATION_AGITATOR = ObjectID.MM_LAB_MACHINE_AGITATOR;
	public static final int STATION_ALEMBIC = ObjectID.MM_LAB_MACHINE_ALEMBIC;
	public static final int VESSEL = ObjectID.MM_LAB_VESSEL;
	public static final int CONVEYOR = ObjectID.MM_LAB_CONVEYOR;
	// digweed spawn spots (multiloc parents, one per corner); their varbit
	// morphs them 0 -> "Young digweed" (always visible, not pickable),
	// 1 -> "Mature digweed" (pickable), 2 -> nothing (cache-verified)
	public static final int HERB_SPOT_1 = ObjectID.MM_HERB_1;
	public static final int HERB_SPOT_2 = ObjectID.MM_HERB_2;
	public static final int HERB_SPOT_3 = ObjectID.MM_HERB_3;
	public static final int HERB_SPOT_4 = ObjectID.MM_HERB_4;
	public static final int[] HERB_SPOTS = {HERB_SPOT_1, HERB_SPOT_2, HERB_SPOT_3, HERB_SPOT_4};
	public static final int HERB_MATURE = ObjectID.MM_HERB_READY;

	/**
	 * Every live instance per id: some lab objects (the conveyor belt) are
	 * the same id repeated once per segment.
	 */
	private final Map<Integer, List<TileObject>> objects = new HashMap<>();

	public void track(TileObject object)
	{
		if (object == null)
		{
			return;
		}
		switch (object.getId())
		{
			case LEVER_MOX:
			case LEVER_AGA:
			case LEVER_LYE:
			case STATION_RETORT:
			case STATION_AGITATOR:
			case STATION_ALEMBIC:
			case VESSEL:
			case CONVEYOR:
			case HERB_SPOT_1:
			case HERB_SPOT_2:
			case HERB_SPOT_3:
			case HERB_SPOT_4:
				objects.computeIfAbsent(object.getId(), k -> new ArrayList<>()).add(object);
				break;
			default:
		}
	}

	public void untrack(TileObject object)
	{
		if (object == null)
		{
			return;
		}
		List<TileObject> list = objects.get(object.getId());
		if (list != null)
		{
			list.remove(object);
			if (list.isEmpty())
			{
				objects.remove(object.getId());
			}
		}
	}

	/**
	 * The most recently spawned instance of an id, or null.
	 */
	public TileObject get(int objectId)
	{
		List<TileObject> list = objects.get(objectId);
		return list == null || list.isEmpty() ? null : list.get(list.size() - 1);
	}

	/**
	 * The instance of an id nearest to a point (e.g. the player), or null.
	 */
	public TileObject nearest(int objectId, LocalPoint to)
	{
		List<TileObject> list = objects.get(objectId);
		if (list == null || list.isEmpty())
		{
			return null;
		}
		if (to == null)
		{
			return list.get(list.size() - 1);
		}
		TileObject best = null;
		int bestDist = Integer.MAX_VALUE;
		for (TileObject o : list)
		{
			LocalPoint p = o.getLocalLocation();
			int d = p == null ? Integer.MAX_VALUE : p.distanceTo(to);
			if (best == null || d < bestDist)
			{
				best = o;
				bestDist = d;
			}
		}
		return best;
	}

	public void clear()
	{
		objects.clear();
	}

	/**
	 * Station object id for an order modifier (1=Agitator, 2=Retort,
	 * 3=Alembic).
	 */
	public static int stationForModifier(int modifier)
	{
		switch (modifier)
		{
			case 1:
				return STATION_AGITATOR;
			case 2:
				return STATION_RETORT;
			case 3:
				return STATION_ALEMBIC;
			default:
				return 0;
		}
	}
}

package com.meowcape.mixologyplus;

